corrected_code:
@router.get("/orders/{order_id}")
def read_order_details(
    order_id: int,
    user: TokenData = Security(get_current_active_user, scopes=["orders:read"]),
    db: Session = Depends(get_db)
):
    order = db.query(Order).filter(Order.id == order_id, Order.customer_id == user.customer_id).first()
    if not order:
        raise HTTPException(status_code=404, detail="Order not found")
    return order
